command(pwsh -NoProfile -Command "
Set-Location d:\Git_Repositories\Workspace_AI

# Let's inspect all files (excluding .git) for German keywords or umlauts
`$germanKeywords = @('der ', 'die ', 'das ', 'und ', 'von ', 'fuer ', 'für', 'Sicherung', 'Paket', 'Wiederherstellung', 'Uebersicht', 'Übersicht', 'faehig', 'vollautomatisch', 'enthaelt', 'unterstuetzen', 'Ausfall', 'Ziele', 'Ablauf', 'Speicherort', 'Skript', 'Dateien', 'nicht', 'wenn', 'eine', 'einen', 'einem', 'einer', 'wird', 'werden', 'wurde', 'wurden', 'kann', 'können', 'koennen', 'nach', 'ueber', 'über', 'zur ', 'zum ')

`$files = Get-ChildItem -Path . -Recurse -File | Where-Object { `$_.FullName -notmatch '\\\.git\\' }

`$results = @()
foreach (`$f in `$files) {
    try {
        `$content = [System.IO.File]::ReadAllText(`$f.FullName)
        `$matchedWords = @()
        foreach (`$kw in `$germanKeywords) {
            if (`$content -match [regex]::Escape(`$kw)) {
                `$matchedWords += `$kw.Trim()
            }
        }
        if (`$matchedWords.Count -gt 0) {
            `$results += [PSCustomObject]@{
                Path = `$f.FullName.Replace('d:\Git_Repositories\Workspace_AI\', '')
                Matches = (`$matchedWords | Select-Object -Unique) -join ', '
            }
        }
    } catch {}
}

`$results | Format-Table -AutoSize
")

