  '\b(der|die|das|dem|den|des|ein|eine|einer|eines|einem|einen)\b',
  '\b(und|oder|aber|denn|weil|dass|da|wenn|als|obwohl)\b',
  '\b(fuer|für|ueber|über|unter|vor|hinter|neben|zwischen|durch|gegen|ohne|um|nach|bei|von|zu|mit|seit|aus)\b',
  '\b(nicht|kein|keine|keinen|keinem|keiner|keines|nichts)\b',
  '\b(ist|sind|war|waren|wird|werden|wurde|wurden|hat|haben|hatte|hatten|kann|können|koennen|muss|müssen|muessen|soll|sollen)\b',
  '\b(Sicherung|Wiederherstellung|Uebersicht|Übersicht|Rekonstruktion|Paket|Pakete|Paketquellen|Dateien|Ordner|Pfad|Pfade|Ziel|Ziele|Ablauf|Speicherort|Schritt|Schritte)\b'
)

`$pattern = `$germanWords -join '|'

`$files = Get-ChildItem -Path . -Recurse -File | Where-Object { 
    `$_.FullName -notmatch '\\\.git\\' -and 
    `$_.FullName -notmatch '\.log$' -and 
