foreach (`$f in `$files) {
    `$lines = Get-Content `$f.FullName
    `$lineNum = 0
    foreach (`$line in `$lines) {
        `$lineNum++
        if (`$line -match `$pattern) {
            # Let's inspect matched tokens
            `$matches = [regex]::Matches(`$line, `$pattern, 'IgnoreCase')
            `$matchList = foreach (`$m in `$matches) { `$m.Value }
            # Filter German specific keywords:
            `$strictlyGerman = `$matchList | Where-Object { 
                `$_ -in @('der','die','das','dem','den','des','ein','eine','einer','eines','einem','einen',
                          'und','oder','aber','denn','weil','dass','wenn','obwohl',
                          'fuer','für','ueber','über','unter','vor','hinter','neben','zwischen','durch','gegen','ohne','nach','bei','von','zu','mit','seit','aus',
                          'nicht','kein','keine','keinen','keinem','keiner','keines','nichts',
