                          'Sicherung','Wiederherstellung','Uebersicht','Übersicht','Rekonstruktion','Paket','Pakete','Paketquellen','Dateien','Ordner','Pfad','Pfade','Ziel','Ziele','Ablauf','Speicherort','Schritt','Schritte')
            }
            if (`$strictlyGerman.Count -gt 0) {
                # Check if it's in an English sentence where the word is actually an English word like 'to', 'or', etc. (already excluded)
                # But 'die' in English is die, 'under' is under, etc.
                Write-Host (`"{0}:{1} [{2}] -> {3}`" -f `$f.FullName.Replace('d:\Git_Repositories\Workspace_AI\', ''), `$lineNum, (`$strictlyGerman -join ','), `$line.Trim())
                `$foundAny = `$true
            }
        }
    }
}

if (-not `$foundAny) {
    Write-Host 'NO GERMAN CONTENT FOUND! Everything is 100% English.'
}
")

command(pwsh -NoProfile -Command "
Set-Location d:\Git_Repositories\Workspace_AI
`$issues = 0
Get-ChildItem -Path . -Recurse -File | Where-Object { 
    `$_.FullName -notmatch '\\\.git\\' -and 
    `$_.FullName -notmatch '\\Deletions\\' -and
    `$_.FullName -notmatch '\.log$' -and
    `$_.FullName -notmatch 'WS_DIR\.txt$'
} | ForEach-Object {
    `$bytes = [System.IO.File]::ReadAllBytes(`$_.FullName)
    `$hasBom = (`$bytes.Length -ge 3 -and `$bytes[0] -eq 0xEF -and `$bytes[1] -eq 0xBB -and `$bytes[2] -eq 0xBF)
    `$text = [System.IO.File]::ReadAllText(`$_.FullName)
    `$hasLfOnly = `$text.Replace(`"`r`n`", `"`").Contains(`"`n`")
    if (`$hasBom -or `$hasLfOnly) {
        Write-Host (`"Format Issue in {0}: HasBOM={1}, HasLfOnly={2}`" -f `$_.FullName, `$hasBom, `$hasLfOnly)
        `$issues++
    }
}
Write-Host (`"Total Format Issues: {0}`" -f `$issues)
")

