command(pwsh -NoProfile -Command "
Set-Location D:\Git_Repositories

`$results = @()
`$dirs = Get-ChildItem -Directory | Sort-Object Name

foreach (`$d in `$dirs) {
  `$hasGit = Test-Path (Join-Path `$d.FullName '.git')
  `$hasLcm = Test-Path (Join-Path `$d.FullName '.lcm\config.json')
  `$hasCopilot = Test-Path (Join-Path `$d.FullName '.copilot')
  `$hasAgents = Test-Path (Join-Path `$d.FullName '.agents')

  `$gitBranch = '-'
  `$gitCommit = '-'
  `$gitStatus = '-'
  `$lcmVer = '-'
  `$classification = 'Unknown'

  if (`$hasGit) {
    try {
      `$gitBranch = (git -C `$d.FullName rev-parse --abbrev-ref HEAD 2>`$null)
      `$gitCommit = (git -C `$d.FullName rev-parse --short HEAD 2>`$null)
      `$statusOutput = (git -C `$d.FullName status --short 2>`$null)
      `$gitStatus = if (`$statusOutput) { 'Dirty' } else { 'Clean' }
    } catch {
      `$gitStatus = 'Git-Error'
    }
  } else {
    `$gitStatus = 'No .git'
  }

  if (`$d.Name -eq 'Workspace_AI') {
    `$classification = 'Active Design Workshop (LCM Engine 4.1.0)'
    `$lcmVer = '4.1.0'
  } elseif (`$hasLcm) {
    try {
      `$cfg = Get-Content -Raw -Path (Join-Path `$d.FullName '.lcm\config.json') | ConvertFrom-Json
      `$lcmVer = `$cfg.governance.lcm_version
      `$classification = `"Onboarded LCM (v`$lcmVer)`"
    } catch {
      `$classification = 'Onboarded LCM (Config Parse Error)'
    }
  } elseif (`$d.Name -eq 'VolumeInventory') {
    `$classification = 'Candidate LCM (v4.0.0 dry-run verified)'
    `$lcmVer = '4.0.0'
  } elseif (-not `$hasGit) {
    `$classification = 'Non-Git (Not LCM)'
  } elseif (`$d.Name -in @('Workspace_AC', 'Workspace_GC')) {
    `$classification = 'Legacy Baseline (Retired)'
  } else {
    `$classification = 'Standard Git Repo (Un-onboarded / Not LCM)'
  }

  `$results += [pscustomobject]@{
    RepositoryName = `$d.Name
    HasGit         = `$hasGit
    Branch         = `$gitBranch
    Commit         = `$gitCommit
    GitStatus      = `$gitStatus
    LCMVersion     = `$lcmVer
    Classification = `$classification
  }
}

`$results | Format-Table -AutoSize
")
